		t.Fatalf("Commit: %v", err)
	}
	tx2 := db.Begin()
	tx2.Set("inv:widget", []byte("11")) // overwrite
	tx2.Delete("inv:gadget")            // tombstone
	tx2.Set("inv:sprocket", []byte("40"))
	if err := tx2.Commit(); err != nil {
		t.Fatalf("Commit: %v", err)
	}
	if err := db.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

