// refBucket is the bucketing contract shared with the JS and Python SDKs:
// FNV-1a 64 over "<flagKey>:<unitID>", modulo 10000 basis points.
func refBucket(key, id string) int {
	h := fnv.New64a()
	h.Write([]byte(key + ":" + id))
	return int(h.Sum64() % 10000)
}

