    void partialBatchesCountAsFullBatches(int unitsOrdered, int unitsPerBatch, int want) {
        assertEquals(want, BatchMath.batchesForOrders(unitsOrdered, unitsPerBatch));
    }

    @Test
    void batchSizeMustBePositive() {
