import com.ovenworks.bakecore.BatchMath;

/** Turns the week's order book into a purchasing list. */
public final class PurchasePlanner {

    private PurchasePlanner() {
    }

    /**
     * One line per ingredient, alphabetical, e.g. {@code "flour: 25830 g"}.
     *
     * <p>Orders map product name to units ordered; each ordered product
     * must have a recipe. Batch counts and the waste allowance come from
     * bake-core's BatchMath.
     */
    public static List<String> plan(Map<String, Integer> orders, List<Recipe> recipes, int wastePct) {
        Map<String, Recipe> recipeByProduct = new HashMap<>();
        for (Recipe recipe : recipes) {
            recipeByProduct.put(recipe.product(), recipe);
        }

        // TreeMap keeps the running ingredient totals in alphabetical order.
        Map<String, Integer> gramsByIngredient = new TreeMap<>();
        for (Map.Entry<String, Integer> entry : orders.entrySet()) {
            int unitsOrdered = entry.getValue();
            if (unitsOrdered == 0) {
                continue;
            }
            String product = entry.getKey();
            Recipe recipe = recipeByProduct.get(product);
            if (recipe == null) {
                throw new IllegalArgumentException("no recipe for \"" + product + "\"");
            }
            int batches = BatchMath.batchesForOrders(unitsOrdered, recipe.unitsPerBatch());
            for (Map.Entry<String, Integer> ingredient : recipe.gramsPerBatch().entrySet()) {
                int grams = BatchMath.gramsWithWaste(ingredient.getValue(), batches, wastePct);
                gramsByIngredient.merge(ingredient.getKey(), grams, Integer::sum);
            }
        }

        List<String> lines = new ArrayList<>(gramsByIngredient.size());
        for (Map.Entry<String, Integer> e : gramsByIngredient.entrySet()) {
            lines.add(e.getKey() + ": " + e.getValue() + " g");
        }
        return lines;
    }
}

