			return ts.Year() == day.Year() && ts.Month() == day.Month() && ts.Day() == day.Day()
		})
	}

	// Weekly buckets: the current ISO week and the preceding Weekly-1
	// weeks. ISOWeek handles week-year rollover around January.
	daysSinceMonday := (int(nowUTC.Weekday()) + 6) % 7 // Mon=0 ... Sun=6
	currentMonday := today.AddDate(0, 0, -daysSinceMonday)
	for w := 0; w < policy.Weekly; w++ {
		monY, monW := currentMonday.AddDate(0, 0, -7*w).ISOWeek()
		claim("weekly", func(ts time.Time) bool {
			ty, tw := ts.ISOWeek()
