	for _, n := range sorted {
		if reason, ok := kept[n]; ok {
			keep = append(keep, Decision{Name: n, Reason: reason})
		} else {
			del = append(del, n)
		}
	}
	return &Plan{Keep: keep, Delete: del}, nil
}

